let docPilotQuitBusy=false;
async function quitDocPilot(event){
 if(docPilotQuitBusy)return;
 docPilotQuitBusy=true;
 const button=event.currentTarget;
 button.disabled=true;button.textContent="Fermeture…";
 const root=document.getElementById("root");
 const panel=document.createElement("div");
 panel.style.cssText="position:fixed;inset:0;z-index:99999;background:#f5faf7;display:grid;place-content:center;padding:30px;text-align:center;font-family:Inter,system-ui;color:#173b31";
 panel.setAttribute("role","dialog");panel.setAttribute("aria-modal","true");panel.setAttribute("aria-label","Fermeture de DocPilot");
 const title=document.createElement("h1"),text=document.createElement("p"),retry=document.createElement("button");
 text.setAttribute("role","status");text.setAttribute("aria-live","polite");
 retry.className="pilot-primary";retry.hidden=true;
 title.textContent="Fermeture de DocPilot…";text.textContent="Les traitements en cours se terminent avant l’arrêt du serveur.";
 panel.append(title,text,retry);document.body.append(panel);if(root)root.inert=true;
 async function request(url,options={},timeout=2500){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);
  try{return await fetch(url,{...options,cache:"no-store",signal:controller.signal})}finally{clearTimeout(timer)}
 }
 function recover(message){
  title.textContent="Fermeture non confirmée";text.textContent=message;
  retry.hidden=false;retry.textContent="Réessayer";retry.onclick=()=>{panel.remove();if(root)root.inert=false;button.disabled=false;button.textContent="Quitter";docPilotQuitBusy=false;quitDocPilot({currentTarget:button})};retry.focus();
 }
 try{
  const response=await request("/api/v1/system/quit",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({quit:true})},8000);
  if(!response.ok){let message="Le serveur refuse la fermeture ("+response.status+").";try{const data=await response.json();if(typeof data.detail==="string")message=data.detail}catch{}throw Error(message)}
  const accepted=await response.json();if(accepted.status!=="stopping")throw Error("Réponse de fermeture inattendue.");
 }catch(error){
  // A timed-out response may still have reached the server. Verify shutdown
  // before inviting another idempotent Quit request.
  if(error.name!=="AbortError"&&!(error instanceof TypeError)){recover(error.message||String(error));return}
  text.textContent="Connexion interrompue. Vérification de l’arrêt du serveur…";
 }
 let failures=0;const deadline=Date.now()+60000;
 async function check(){
  if(Date.now()>deadline){recover("Le serveur répond encore ou son arrêt ne peut pas être confirmé. Un traitement peut être en cours ; réessayez dans un instant.");return}
  try{await request("/api/v1/health");failures=0}
  catch(error){if(error.name!=="AbortError")failures++;else failures=0}
  if(failures>=3){title.textContent="DocPilot est fermé";text.textContent="Tu peux fermer cet onglet. Pour reprendre, lance DocPilot depuis son raccourci.";return}
  setTimeout(check,1000);
 }
 setTimeout(check,1000);
}

