function inlineFilingMissingFields(doc,kind){
 const missing=[];
 if(archiveDuplicateFound(doc))missing.push("doublon déjà présent dans l’archive");
 if(!doc.legal_entity_id)missing.push("fournisseur");
 if(!doc.creditor_id)missing.push("société");
 if(!doc.proposed_filename)missing.push("nom du fichier");
 if(archiveMonetary(kind)){
  if(!doc.invoice_date)missing.push("date de facture"+(doc.confidence?.invoice_date?.method==="document_conflict"?" (dates contradictoires détectées)":""));
  if(doc.amount_minor==null)missing.push("montant");
  if(!doc.currency)missing.push("devise");
 }
 if(doc.error_message)missing.push(doc.error_message);
 return missing;
}

function docPilotFolderPath(value){
 let path=String(value||"").replace(/\\/g,"/");
 const network=path.startsWith("//");
 path=path.replace(/\/+/g,"/");
 if(network)path="/"+path;
 path=path.replace(/\/$/,"");
 return /^[A-Za-z]:$/.test(path)?path+"/":path;
}
function docPilotFolderRoot(value){
 const path=docPilotFolderPath(value);
 if(/^[A-Za-z]:\//.test(path))return path.slice(0,3);
 if(path.startsWith("//"))return path.split("/").slice(0,4).join("/");
 return "/";
}
function docPilotFolderParent(value){
 const path=docPilotFolderPath(value),root=docPilotFolderRoot(path);
 if(path===root)return "";
 const parent=path.slice(0,path.lastIndexOf("/"));
 return parent.length<root.length?root:docPilotFolderPath(parent);
}
function docPilotArchiveRelative(value,root){
 const path=docPilotFolderPath(value),base=docPilotFolderPath(root).replace(/\/$/,"");
 return base&&path.toLowerCase().startsWith(base.toLowerCase()+"/")?path.slice(base.length+1):"";
}

