  loading&&o.jsx('p',{role:'status',children:'Chargement…'}),
  error&&o.jsx('p',{className:'pilot-alert error',role:'alert',children:error}),
  o.jsxs('div',{className:'pilot-folder-list',children:[docPilotFolderParent(current)&&o.jsx('button',{disabled:loading,onClick:()=>browse(docPilotFolderParent(current)),children:'↑ Dossier parent'}),entries.map(entry=>o.jsx('button',{disabled:loading,onClick:()=>browse(entry.path),children:'📁 '+entry.name},entry.path)),!loading&&current&&!entries.length&&o.jsx('p',{children:'Aucun sous-dossier'})]}),
  !relative&&o.jsx('p',{role:'status',children:'Choisissez un dossier dans l’archive de cette société : '+root}),
  o.jsxs('div',{className:'pilot-modal-actions',children:[o.jsx('button',{className:'pilot-secondary',onClick:onClose,children:'Annuler'}),o.jsx('button',{className:'pilot-primary',disabled:loading||!relative,onClick:choose,children:'Choisir ce dossier'})]})
